class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0
        for i in range(n):
            # Compare with next element, wrapping around for the last element
            next_idx = (i + 1) % n
            diff = abs(nums[i] - nums[next_idx])
            if diff > max_diff:
                max_diff = diff
        return max_diff
