class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        if k > n:
            return False

        # Check each possible starting position for a substring of length k
        for i in range(n - k + 1):
            # Check if all characters in s[i:i+k] are the same
            char = s[i]
            all_same = True
            for j in range(i, i + k):
                if s[j] != char:
                    all_same = False
                    break

            if not all_same:
                continue

            # Check character before (if exists)
            if i > 0 and s[i - 1] == char:
                continue

            # Check character after (if exists)
            if i + k < n and s[i + k] == char:
                continue

            return True

        return False
