class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        for i in range(n - k + 1):
            # Check if substring s[i:i+k] consists of only one distinct character
            substring = s[i:i+k]
            if len(set(substring)) != 1:
                continue

            char = substring[0]

            # Check character immediately before (if exists)
            if i > 0:
                if s[i-1] == char:
                    continue

            # Check character immediately after (if exists)
            if i + k < n:
                if s[i+k] == char:
                    continue

            # All conditions satisfied
            return True

        return False
