class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0

        for i in range(n):
            is_good = True

            # Check left neighbor at i - k
            left_idx = i - k
            if left_idx >= 0:
                if nums[i] <= nums[left_idx]:
                    is_good = False

            # Check right neighbor at i + k
            right_idx = i + k
            if right_idx < n:
                if nums[i] <= nums[right_idx]:
                    is_good = False

            if is_good:
                total += nums[i]

        return total
