class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def is_beautiful(n: int) -> bool:
            digits = []
            temp = n
            while temp > 0:
                digits.append(temp % 10)
                temp //= 10
            digit_sum = sum(digits)
            digit_product = 1
            for d in digits:
                digit_product *= d
            # Check if product is divisible by sum
            # Note: sum of digits is always positive for positive integers
            return digit_product % digit_sum == 0

        count = 0
        for num in range(l, r + 1):
            if is_beautiful(num):
                count += 1
        return count
