class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # Convert each property list to a set for efficient intersection
        prop_sets = [set(p) for p in properties]

        # Build adjacency list
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct common integers
                common = len(prop_sets[i] & prop_sets[j])
                if common >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Find connected components using BFS/DFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                # BFS
                queue = [i]
                visited[i] = True
                while queue:
                    node = queue.pop(0)
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return components
