    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # Maximum number of containers is limited by:
        # 1. The number of cells on the deck: n * n
        # 2. The weight capacity: maxWeight // w

        return min(n * n, maxWeight // w)
