class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Get all substrings of s and t
        def get_substrings(str_):
            subs = set()
            n = len(str_)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    subs.add(str_[i:j])
            return subs

        s_subs = get_substrings(s)
        t_subs = get_substrings(t)

        # Add empty string to both sets (substring can be empty)
        s_subs.add("")
        t_subs.add("")

        # Check all combinations
        max_len = 0

        # Check palindromes from s alone
        for sub in s_subs:
            if sub == sub[::-1]:
                max_len = max(max_len, len(sub))

        # Check palindromes from t alone
        for sub in t_subs:
            if sub == sub[::-1]:
                max_len = max(max_len, len(sub))

        # Check palindromes from concatenation of s_sub + t_sub
        for sub_s in s_subs:
            for sub_t in t_subs:
                combined = sub_s + sub_t
                if combined == combined[::-1]:
                    max_len = max(max_len, len(combined))

        return max_len
